const http = require('http');
const path = require('path');
const { URL } = require('url');
const ejs = require('ejs');

function matchPath(routePattern, actualPath) {
  const cleanPattern = routePattern === '/' ? '' : routePattern.replace(/\/+$/, '');
  const cleanActual = actualPath === '/' ? '' : actualPath.replace(/\/+$/, '');

  const patternParts = cleanPattern.split('/').filter(Boolean);
  const actualParts = cleanActual.split('/').filter(Boolean);

  if (patternParts.length !== actualParts.length) return null;

  const params = {};
  for (let i = 0; i < patternParts.length; i++) {
    const p = patternParts[i];
    const a = actualParts[i];
    if (p.startsWith(':')) {
      params[p.slice(1)] = decodeURIComponent(a);
    } else if (p !== a) {
      return null;
    }
  }
  return params;
}

function createRouter() {
  const routes = [];

  const router = {
    _isRouter: true,
    routes,
    get(subpath, handler) {
      routes.push({ method: 'GET', subpath, handler });
      return this;
    },
    post(subpath, handler) {
      routes.push({ method: 'POST', subpath, handler });
      return this;
    },
    patch(subpath, handler) {
      routes.push({ method: 'PATCH', subpath, handler });
      return this;
    },
    put(subpath, handler) {
      routes.push({ method: 'PUT', subpath, handler });
      return this;
    },
    delete(subpath, handler) {
      routes.push({ method: 'DELETE', subpath, handler });
      return this;
    }
  };

  return router;
}

function createExpressApp() {
  const settings = {
    views: path.resolve(process.cwd(), 'views'),
    'view engine': 'ejs'
  };
  const mounts = [];

  const app = function (req, res) {
    app._handle(req, res);
  };

  app.set = function (key, val) {
    settings[key] = val;
    return app;
  };

  app.get = function (key, handler) {
    if (handler === undefined) return settings[key];
    mounts.push({ type: 'route', method: 'GET', path: key, handler });
    return app;
  };

  app.post = function (routePath, handler) {
    mounts.push({ type: 'route', method: 'POST', path: routePath, handler });
    return app;
  };

  app.patch = function (routePath, handler) {
    mounts.push({ type: 'route', method: 'PATCH', path: routePath, handler });
    return app;
  };

  app.use = function (arg1, arg2) {
    if (typeof arg1 === 'string' && arg2 && arg2._isRouter) {
      mounts.push({ type: 'router', prefix: arg1, router: arg2 });
    } else if (typeof arg1 === 'function') {
      mounts.push({ type: 'middleware', handler: arg1 });
    }
    return app;
  };

  app._handle = async function (req, res) {
    const parsedUrl = new URL(req.url || '/', 'http://localhost');
    const pathname = parsedUrl.pathname;
    req.query = Object.fromEntries(parsedUrl.searchParams.entries());
    req.params = {};

    res.statusCode = 200;
    res.status = function (code) {
      res.statusCode = code;
      return res;
    };
    res.json = function (obj) {
      if (!res.headersSent) {
        res.setHeader('Content-Type', 'application/json; charset=utf-8');
      }
      res.end(JSON.stringify(obj));
      return res;
    };
    res.send = function (body) {
      if (typeof body === 'object' && body !== null) {
        return res.json(body);
      }
      if (!res.headersSent) {
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
      }
      res.end(String(body));
      return res;
    };
    res.render = function (viewName, locals = {}) {
      const ext = settings['view engine'] || 'ejs';
      const file = path.join(settings.views, viewName.endsWith(`.${ext}`) ? viewName : `${viewName}.${ext}`);
      const html = ejs.renderFile(file, locals);
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.end(html);
      return res;
    };

    // Parse body if present
    await new Promise((resolve) => {
      const chunks = [];
      req.on('data', (c) => chunks.push(c));
      req.on('end', () => {
        const raw = Buffer.concat(chunks).toString('utf8');
        if (!raw) {
          req.body = {};
          return resolve();
        }
        const ct = (req.headers['content-type'] || '').toLowerCase();
        if (ct.includes('application/json')) {
          try {
            req.body = JSON.parse(raw);
          } catch (_) {
            req.body = {};
          }
        } else if (ct.includes('application/x-www-form-urlencoded')) {
          req.body = Object.fromEntries(new URLSearchParams(raw).entries());
        } else {
          try {
            req.body = JSON.parse(raw);
          } catch (_) {
            req.body = {};
          }
        }
        resolve();
      });
    });

    for (const m of mounts) {
      if (m.type === 'route' && m.method === req.method) {
        const params = matchPath(m.path, pathname);
        if (params) {
          req.params = params;
          await m.handler(req, res);
          return;
        }
      } else if (m.type === 'router') {
        const prefix = m.prefix.replace(/\/+$/, '');
        for (const r of m.router.routes) {
          if (r.method !== req.method) continue;
          const sub = r.subpath === '/' ? '' : r.subpath;
          const fullPattern = `${prefix}${sub}` || '/';
          const params = matchPath(fullPattern, pathname);
          if (params) {
            req.params = params;
            await r.handler(req, res);
            return;
          }
        }
      }
    }

    res.status(404).json({ error: `Rota não encontrada: ${req.method} ${pathname}` });
  };

  app.listen = function (port, cb) {
    const server = http.createServer(app);
    return server.listen(port, cb);
  };

  return app;
}

createExpressApp.Router = createRouter;
createExpressApp.json = () => (req, res, next) => next && next();
createExpressApp.urlencoded = () => (req, res, next) => next && next();

module.exports = createExpressApp;
